const $=s=>document.querySelector(s);const profiles=[{name:'민준',age:32,job:'백엔드 개발자',place:'성수',initial:'MJ',score:92,tags:['Java','Spring','주 2회 재택'],bio:'복잡한 코드는 단순하게, 소중한 관계는 깊이 있게. 주말엔 같이 새로운 카페를 찾아요.',reason:'진지한 관계를 원하고, 평일 저녁의 여유를 좋아해요.'},{name:'서연',age:29,job:'프론트엔드 개발자',place:'연남',initial:'SY',score:89,tags:['React','TypeScript','전시 산책'],bio:'화면의 작은 디테일과 일상의 작은 행복을 좋아해요. 좋은 전시를 보면 같이 가고 싶어요.',reason:'새로운 공간을 찾아다니고, 함께하는 시간을 중요하게 생각해요.'},{name:'지훈',age:31,job:'iOS 개발자',place:'판교',initial:'JH',score:87,tags:['Swift','주말 러닝','커피'],bio:'평일에는 앱을, 주말에는 건강한 루틴을 만들어요. 러닝 끝에 마시는 커피 한 잔이면 충분해요.',reason:'꾸준한 일상과 솔직한 대화를 중요하게 생각해요.'},{name:'하은',age:28,job:'프로덕트 디자이너',place:'합정',initial:'HE',score:85,tags:['Design','독립서점','영화'],bio:'사람을 이해하는 일을 해요. 서로의 취향을 하나씩 알아가는 느린 만남이면 좋겠어요.',reason:'서로의 일을 존중하고, 취향을 나누는 관계를 원해요.'},{name:'도윤',age:30,job:'데이터 엔지니어',place:'잠실',initial:'DY',score:84,tags:['Python','요리','산책'],bio:'데이터 속 패턴을 찾지만, 만남에는 정답이 없다고 믿어요. 맛있는 저녁은 제가 만들게요.',reason:'편안한 대화와 소소한 저녁 시간을 좋아해요.'}];let index=0,page='discover',likes=[],matched=false,role='dev',pref='all',verified=[false,false],messages=[],filter='all',chatOpen=false;
const paths={discover:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',likes:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 1 10 8 15 7-5 12-11 8-15Z"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9H4l-2 2V11a9 9 0 0 1 19 0Z"/>',me:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>'};
function nav(){ $('#nav').style.display='flex';$('#nav').innerHTML=Object.entries({discover:'발견',likes:'호감',chat:'대화',me:'마이'}).map(([k,v])=>`<button class="${page===k?'selected':''}" onclick="go('${k}')" aria-label="${v}" ${page===k?'aria-current="page"':''}><svg viewBox="0 0 24 24">${paths[k]}</svg>${v}</button>`).join('')}
function go(p){page=p;chatOpen=false;nav();if(p==='discover')discover();if(p==='likes')renderLikes();if(p==='chat')chats();if(p==='me')me();window.scrollTo(0,0)}
function discover(){let p=profiles[index];$('#main').innerHTML=`<div class="topline"><h2>오늘의 발견<span class="syntax">.</span></h2><span class="count">${Math.min(index+1,5).toString().padStart(2,'0')} <span>/ 05</span></span></div><div class="filter-row"><button class="pill ${filter==='all'?'active':''}" onclick="setFilter('all')">전체</button><button class="pill ${filter==='dev'?'active':''}" onclick="setFilter('dev')">개발자</button><button class="pill filter" onclick="filters()" aria-label="추천 조건 설정">필터 <span>⌘</span></button></div>${index>=5?`<div class="empty"><div class="big">// end of today</div><h3>오늘의 추천을 모두 봤어요</h3><p>내일 새로운 인연을 소개할게요.</p><button class="btn secondary full" onclick="index=0;discover()">다시 보기</button></div>`:`<article class="profile"><div class="file-tab"><span class="file-icon">ts</span> ${p.initial.toLowerCase()}.profile.ts <span class="tab-end">×</span></div><div class="profile-heading"><div><div class="profile-name">${p.name}<span>${p.age}</span><b title="인증 완료">✓</b></div><p>${p.job} <span>· ${p.place}</span></p></div><div class="initial-box">${p.initial}<span>_</span></div></div><div class="code-block" aria-label="프로필 정보"><div class="code-line"><i>01</i><code><span class="keyword">const</span> <span class="variable">${p.initial.toLowerCase()}</span> = {</code></div><div class="code-line"><i>02</i><code>&nbsp; stack: [<span class="string">"${p.tags[0]}"</span>${['Java','React'].includes(p.tags[0])?`, <span class="string">"${p.tags[1]}"</span>`:''}],</code></div><div class="code-line"><i>03</i><code>&nbsp; afterWork: <span class="string">"${['카페 탐방','전시 산책','러닝과 커피','독립서점','요리와 산책'][index]}"</span>,</code></div><div class="code-line"><i>04</i><code>&nbsp; lookingFor: <span class="string">"진지한 관계"</span>,</code></div><div class="code-line"><i>05</i><code>&nbsp; verified: <span class="keyword">true</span></code></div><div class="code-line"><i>06</i><code>};</code></div></div><div class="profile-body"><p class="section-comment">// about me</p><p class="bio">${p.bio}</p><div class="reason"><div class="reason-top"><span>함께 맞는 점</span><b>${p.score}<small>%</small></b></div><p>${p.reason}</p></div><div class="verified"><span>✓</span> ${p.job.includes('개발')||p.job.includes('엔지니어')?'회사 이메일 · GitHub 인증':'회사 이메일 인증'}</div></div></article><div class="actions"><button class="btn secondary" onclick="skip()">건너뛰기 <span>→</span></button><button class="btn" onclick="like()">♡ &nbsp;${likes.includes(index)?'호감 보냈어요':'호감 보내기'}</button></div><p class="footnote">서로 호감을 보내면 대화가 열려요.</p>`}`}
function skip(){index++;if(filter==='dev'&&index===3)index++;discover()}
function setFilter(f){filter=f;index=0;discover()}
function like(){if(likes.includes(index)){toast('이미 호감을 보낸 프로필이에요');return}likes.push(index);if(index===0){matched=true;show(`<button class="close" onclick="closeModal()" aria-label="닫기">×</button><p class="eyebrow">// connection established</p><div class="gradient-title">match = true;</div><h2>민준님과 마음이 통했어요.</h2><p class="muted">서로에게 호감을 보냈어요.<br>이제 두 사람의 이야기를 시작해 볼까요?</p><div class="panel"><span class="eyebrow">// shared interests</span><p>☕ 새로운 카페 찾기 · 진지한 관계</p></div><button class="btn full" onclick="closeModal();go('chat');openChat()">첫 인사 보내기</button><button class="btn secondary full" style="margin-top:10px" onclick="closeModal();skip()">조금 더 둘러보기</button>`)}else{toast('호감을 보냈어요');skip()}}
function renderLikes(){ $('#main').innerHTML=`<p class="eyebrow">// likes</p><h2>보낸 호감</h2><p class="intro">내가 보낸 호감 ${likes.length}</p>${likes.length?likes.map(i=>`<button class="listrow" onclick="index=${i};go('discover')"><span class="small-avatar">${profiles[i].initial}</span><span><strong>${profiles[i].name}, ${profiles[i].age}</strong><small>${profiles[i].job} · ${i===0?'서로 호감을 보냈어요':'상대의 답변을 기다리고 있어요'}</small></span><time>♡</time></button>`).join(''):`<div class="empty"><div class="big">♡</div><h3>작은 용기로 시작해요</h3><p>마음이 가는 사람에게 호감을 보내보세요.</p><button class="btn full" onclick="go('discover')">오늘의 추천 보기</button></div>`}`}
function chats(){$('#main').innerHTML=`<p class="eyebrow">// messages</p><h2>대화</h2><p class="intro">서로 호감을 보낸 사람과 대화해요.</p>${matched?`<button class="listrow" onclick="openChat()"><span class="small-avatar">MJ</span><span><strong>민준 <span style="color:#0099ff">✓</span></strong><small>${messages.length?'보낸 메시지가 있어요':'마음이 통했어요. 첫 인사를 건네보세요.'}</small></span><time>NEW</time></button>`:`<div class="empty"><div class="big">{ hi }</div><h3>아직은, 첫 인사 전</h3><p>서로 호감을 보내면<br>이곳에서 대화를 나눌 수 있어요.</p><button class="btn full" onclick="go('discover')">인연 만나러 가기</button></div>`}`}
function escapeText(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function openChat(){chatOpen=true;$('#main').innerHTML=`<button class="back" onclick="go('chat')">← 대화 목록</button><div class="listrow"><span class="small-avatar">MJ</span><strong>민준 <span style="color:#0099ff">✓</span></strong><button class="icon" onclick="safety()" aria-label="대화 안전 설정">⋯</button></div><p class="tip">서로의 마음이 연결되었어요 · 오늘</p><div class="panel"><p class="eyebrow">// first message</p><p>둘 다 새로운 카페 찾기를 좋아해요.</p><button class="pill" onclick="$('#message').value='요즘 가장 좋았던 카페가 있나요?';$('#message').focus()">요즘 가장 좋았던 카페가 있나요? ↗</button></div><div id="messages">${messages.map(m=>`<div class="bubble mine">${escapeText(m)}</div>`).join('')}</div><form class="chat-form" onsubmit="send(event)"><input id="message" aria-label="메시지" placeholder="부담 없이, 첫 인사를 건네세요" maxlength="1000" autocomplete="off"><button aria-label="메시지 보내기">↑</button></form><p class="tip">목업 대화예요. 실제 상대에게 전송되지 않아요.</p>`}
function send(e){e.preventDefault();const t=$('#message').value.trim();if(!t)return;messages.push(t);openChat();$('#message').focus()}
function me(){$('#main').innerHTML=`<p class="eyebrow">// my.profile</p><h2>나의 프로필</h2><div class="profile-self"><div class="small-avatar">ME</div><h3>${su.nick?escapeText(su.nick):'내 프로필'}</h3><span class="muted">${role==='dev'?'개발자':'개발자를 만나고 싶은 사람'} · 체험 프로필</span></div><div class="panel"><h3>프로필 인증</h3><p class="muted">나에게 필요한 인증을 확인해 보세요.</p><button class="btn full" onclick="suJump(2)">인증 체험하기</button></div><button class="settings-row" onclick="suJump(4)">만나고 싶은 사람<span>${pref==='all'?'상관없어요':pref==='dev'?'개발자':'비개발자'} ›</span></button><button class="settings-row" onclick="filters()">만남 선호 설정<span>변경 ›</span></button><button class="settings-row" onclick="su.vi=0;su.ans=[];suJump(3)">가치관 O/X<span>${suTags().length?suTags().length+' / 8 답변':'시작'} ›</span></button><button class="settings-row" onclick="suReplay()">가입 흐름 처음부터 보기<span>init ›</span></button><p class="tip">이 목업의 프로필과 인증 내역은 가상 데이터입니다.</p>`}
const suQ=[{c:'일상',t:'주말 계획은 미리 정해두는 편이에요.',o:'계획형',x:'즉흥형'},{c:'일상',t:'하루 중 혼자 있는 시간이 꼭 필요해요.',o:'혼자 시간 필요',x:'함께가 편함'},{c:'연애',t:'연애 중에는 매일 연락하는 게 당연하다고 생각해요.',o:'매일 연락',x:'연락은 자유롭게'},{c:'연애',t:'다툼은 그날 안에 풀어야 마음이 편해요.',o:'그날 해결',x:'시간이 필요'},{c:'커리어',t:'일보다 삶의 균형이 먼저예요.',o:'워라밸 우선',x:'성장 우선'},{c:'커리어',t:'퇴근 후에도 공부나 사이드 프로젝트를 이어가요.',o:'사이드 프로젝트',x:'퇴근 후 off'},{c:'외모',t:'편안한 옷차림이 저에게는 가장 중요해요.',o:'편안함 우선',x:'스타일 우선'},{c:'외모',t:'첫 만남에서는 외모보다 분위기와 태도가 먼저 보여요.',o:'분위기 중심',x:'첫인상 중심'}];
let su={role:'',nick:'',email:'',github:'',pref:'',rel:'',time:'',vi:0,ans:[]};
function suReset(){su={role:'',nick:'',email:'',github:'',pref:'',rel:'',time:'',vi:0,ans:[]}}
function suReplay(){suReset();signup(0)}
function suJump(s){if(!su.role)su.role=role;if(!su.pref)su.pref=pref;if(!su.nick)su.nick='나';if(!su.email)su.email=verified[0]?'ok':'';if(!su.github)su.github=verified[1]?'ok':'';signup(s)}
function suPick(k,v){su[k]=v;signup(k==='role'?1:4)}
function suVerify(k){if(su[k])return;su[k]='ing';signup(2);setTimeout(()=>{su[k]='ok';signup(2);toast(k==='email'?'회사 이메일 인증이 완료되었어요':'GitHub 계정을 연결했어요')},650)}
function suGate(){const b=$('#go1');if(b)b.disabled=!(su.role&&su.nick);const p=$('#prevbox');if(p)p.innerHTML=suPrev()}
function suAnswer(v){su.ans[su.vi]=v;su.vi++;su.vi>=suQ.length?signup(4):signup(3)}
function suPrevQ(){if(su.vi){su.vi--;signup(3)}else signup(2)}
function suTags(){return su.ans.map((a,i)=>a===null||a===undefined?null:(a?suQ[i].o:suQ[i].x)).filter(Boolean)}
function suHead(n,label,act){return `<button class="back" onclick="${act}">← 이전</button><div class="step">${[1,2,3,4].map(i=>`<i class="${i<=n?'done':''}"></i>`).join('')}</div><p class="eyebrow">0${n} / 04 · ${label}</p>`}
function suPrev(){const L=[];if(su.role)L.push(['role',su.role==='dev'?'"developer"':'"open"']);if(su.nick)L.push(['name',`"${escapeText(su.nick)}"`]);const v=[su.email==='ok'?'"email"':'',su.github==='ok'?'"github"':''].filter(Boolean);if(v.length)L.push(['verified',`[${v.join(', ')}]`]);const a=suTags().length;if(a)L.push(['values',`${a} / 8`]);if(su.pref)L.push(['lookingFor',su.pref==='dev'?'"developer"':su.pref==='other'?'"non-developer"':'"anyone"']);return L.length?`<div class="prev"><div class="file-tab"><span class="file-icon">ts</span> me.profile.ts <span class="tab-end">•</span></div><div class="code-block">${L.map((l,i)=>`<div class="code-line"><i>0${i+1}</i><code>&nbsp; ${l[0]}: <span class="string">${l[1]}</span>,</code></div>`).join('')}</div></div>`:''}
function vrow(k,sym,title,desc){const s=su[k];return `<button class="option ${s==='ok'?'selected':''}" onclick="suVerify('${k}')" aria-pressed="${s==='ok'}"><span class="symbol">${sym}</span><span><strong>${title}</strong><small>${s==='ok'?'확인이 완료되었어요':s==='ing'?'확인하는 중이에요':desc}</small></span><span class="tag ${s==='ok'?'ok':s==='ing'?'ing':''}">${s==='ok'?'✓ done':s==='ing'?'···':'인증'}</span></button>`}
function signup(step){page='signup';chatOpen=false;$('#nav').style.display='none';const m=$('#main');
if(step===0)m.innerHTML=`<p class="prompt"><span>$</span>devmeet init<i class="cursor"></i></p><h2 class="onboard-hero">코드 밖에서도,<br>말이 통하는 사람.</h2><p class="onboard-lead">검증된 개발자와, 개발자를 만나고 싶은 사람.<br>가입은 1분이면 끝나요.</p><ul class="checks"><li><b>01</b> 회사 이메일과 GitHub로 신원을 확인해요</li><li><b>02</b> 가치관 O/X 8문항으로 결이 맞는 사람을 찾아요</li><li><b>03</b> 서로 호감을 보냈을 때만 대화가 열려요</li></ul><button class="btn full" onclick="signup(1)">계정 만들기 →</button><button class="btn secondary full" style="margin-top:10px" onclick="suEnter()">이미 계정이 있어요 · 바로 둘러보기</button><p class="footnote">입력한 정보는 추천에만 쓰이고, 인증 내용은 공개되지 않아요.</p>`;
else if(step===1)m.innerHTML=`${suHead(1,'IDENTITY',"signup(0)")}<h2 class="onboard-hero">어떤 사람인가요?</h2><p class="onboard-lead">역할에 따라 꼭 필요한 인증만 요청해요.</p>${option('dev','⌨','저는 개발자예요','회사 이메일 · GitHub로 인증해요',su.role,"suPick('role','dev')")}${option('other','✧','개발자를 만나고 싶어요','회사 이메일만 인증하면 돼요',su.role,"suPick('role','other')")}<label class="formlabel" for="nick">프로필에 표시될 이름</label><input id="nick" maxlength="12" autocomplete="off" placeholder="예: 민준" value="${escapeText(su.nick)}" oninput="su.nick=this.value.trim();suGate()"><div id="prevbox">${suPrev()}</div><button class="btn full" id="go1" ${su.role&&su.nick?'':'disabled'} onclick="signup(2)">다음 →</button><p class="footnote">이름은 언제든 바꿀 수 있어요.</p>`;
else if(step===2){const need=su.role==='dev',ok=su.email==='ok'&&(!need||su.github==='ok');m.innerHTML=`${suHead(2,'TRUST',"signup(1)")}<h2 class="onboard-hero">딱 한 번,<br>신뢰를 확인해요.</h2><p class="onboard-lead">인증 정보는 공개되지 않고, 프로필에는 배지만 남아요.</p>${vrow('email','@','회사 이메일','회사 도메인으로 재직을 확인해요')}${need?vrow('github','GH','GitHub 계정','활동 이력으로 직무를 교차 확인해요'):''}<div class="panel secure"><span class="eyebrow" style="display:block;margin:0 0 9px">// why verify</span>개발자 사칭과 허위 프로필을 줄이기 위한 과정이에요.<br>서로 안심하고 호감을 보낼 수 있도록.</div><div id="prevbox">${suPrev()}</div><button class="btn full" ${ok?'':'disabled'} onclick="signup(3)">${ok?'인증 완료하고 계속 →':'위 항목을 인증해 주세요'}</button><p class="footnote">목업이라 누르면 바로 인증돼요.</p>`}
else if(step===3){const q=suQ[su.vi];m.innerHTML=`${suHead(3,'VALUES',"suPrevQ()")}<h2 class="onboard-hero">가치관 O/X</h2><p class="onboard-lead">8문항이면 충분해요. 답할수록 추천이 정확해져요.</p><div class="ox"><div class="ox-top"><span class="cat">${q.c}</span><b>${String(su.vi+1).padStart(2,'0')}<span> / 0${suQ.length}</span></b></div><p class="ox-q">${q.t}</p><div class="progress"><i style="width:${(su.vi+1)/suQ.length*100}%"></i></div></div><div class="ox-actions"><button class="btn secondary" onclick="suAnswer(false)">✕ 아니요 <b>false</b></button><button class="btn" onclick="suAnswer(true)">○ 네 <b>true</b></button></div><button class="skip" onclick="suAnswer(null)">잘 모르겠어요 · 건너뛰기</button>`}
else if(step===4)m.innerHTML=`${suHead(4,'PREFERENCE',"su.vi=suQ.length-1;signup(3)")}<h2 class="onboard-hero">누구를 만나고 싶나요?</h2><p class="onboard-lead">언제든 설정에서 바꿀 수 있어요.</p>${option('dev','⌨','개발자','일의 언어가 통하는 사람',su.pref,"suPick('pref','dev')")}${option('other','✧','비개발자','새로운 시선을 가진 사람',su.pref,"suPick('pref','other')")}${option('all','∞','상관없어요','성향과 마음의 결이 더 중요해요',su.pref,"suPick('pref','all')")}<label class="formlabel" for="relationship">연애 가치관</label><select id="relationship"><option>진지한 관계를 원해요</option><option>천천히 알아가고 싶어요</option></select><label class="formlabel" for="schedule">편한 만남 시간</label><select id="schedule"><option>평일 저녁</option><option>주말 오후</option><option>유연하게 만나요</option></select><div id="prevbox">${suPrev()}</div><button class="btn full" ${su.pref?'':'disabled'} onclick="suFinish()">프로필 완성하기 →</button>`;
else{const t=suTags();m.innerHTML=`<p class="eyebrow">// build complete</p><h2 class="onboard-hero">프로필이 만들어졌어요.</h2><p class="onboard-lead">이제 오늘의 추천 5명을 만나볼 차례예요.</p><article class="profile"><div class="file-tab"><span class="file-icon">ts</span> me.profile.ts <span class="tab-end">✓</span></div><div class="code-block"><div class="code-line"><i>01</i><code><span class="keyword">const</span> <span class="variable">me</span> = {</code></div><div class="code-line"><i>02</i><code>&nbsp; name: <span class="string">"${escapeText(su.nick)}"</span>,</code></div><div class="code-line"><i>03</i><code>&nbsp; role: <span class="string">"${su.role==='dev'?'developer':'open'}"</span>,</code></div><div class="code-line"><i>04</i><code>&nbsp; verified: [<span class="string">"email"</span>${su.github==='ok'?', <span class="string">"github"</span>':''}],</code></div><div class="code-line"><i>05</i><code>&nbsp; values: <span class="keyword">${t.length}</span>,</code></div><div class="code-line"><i>06</i><code>&nbsp; lookingFor: <span class="string">"${su.pref==='dev'?'developer':su.pref==='other'?'non-developer':'anyone'}"</span></code></div><div class="code-line"><i>07</i><code>};</code></div></div><div class="profile-body"><p class="section-comment">// my values</p><div class="chips">${t.length?t.map(x=>`<span>${x}</span>`).join(''):'<span>아직 답한 문항이 없어요</span>'}</div><div class="verified" style="margin-top:20px"><span>✓</span> ${su.github==='ok'?'회사 이메일 · GitHub 인증 완료':'회사 이메일 인증 완료'}</div></div></article><button class="btn full" onclick="suEnter()">오늘의 추천 5명 보기 →</button><p class="tip">가치관 답변은 마이에서 언제든 다시 할 수 있어요.</p>`}
window.scrollTo(0,0)}
function suFinish(){const r=$('#relationship'),s=$('#schedule');if(r)su.rel=r.value;if(s)su.time=s.value;signup(5)}
function suEnter(){try{localStorage.setItem('devmeet.onboarded','1')}catch(e){}role=su.role||'dev';pref=su.pref||'all';verified=[su.email==='ok',su.github==='ok'];filter=pref==='dev'?'dev':'all';index=pref==='other'?3:0;go('discover');toast(su.nick?`${su.nick}님을 위한 오늘의 추천이 준비됐어요`:'오늘의 추천이 준비됐어요')}
function booted(){try{return localStorage.getItem('devmeet.onboarded')==='1'}catch(e){return false}}
function option(id,sym,title,desc,current,action){return `<button class="option ${id===current?'selected':''}" onclick="${action}" aria-pressed="${id===current}"><span class="symbol">${sym}</span><span><strong>${title}</strong><small>${desc}</small></span><span class="end">${id===current?'✓':'›'}</span></button>`}
function show(html){$('#modal').innerHTML=html;$('#modal').showModal()}function closeModal(){$('#modal').close()}function filters(){show(`<button class="close" onclick="closeModal()" aria-label="닫기">×</button><p class="eyebrow">// preferences</p><h2>어떤 연결을 원하세요?</h2><label class="formlabel" for="job-filter">만나고 싶은 사람</label><select id="job-filter"><option value="all">직군 상관없어요</option><option value="dev" ${filter==='dev'?'selected':''}>개발자</option></select><p class="secure" style="margin-top:25px">직업 인증과 함께 연애관, 일상의 취향을 살펴 추천해요.</p><button class="btn full" onclick="filter=$('#job-filter').value;index=0;closeModal();booted()?go('discover'):signup(0);toast('추천 조건을 적용했어요')">추천에 반영하기</button>`)}function safety(){show(`<button class="close" onclick="closeModal()" aria-label="닫기">×</button><h2>안전한 대화를 위해</h2><p class="muted">개인 연락처와 금융 정보는 신중하게 공유해 주세요.</p><button class="btn secondary full" onclick="closeModal();toast('목업: 신고가 접수되었어요')">신고하기</button><button class="btn full" onclick="matched=false;messages=[];closeModal();go('chat');toast('대화 연결을 해제했어요')">대화 연결 해제</button>`)}let timer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});booted()?go('discover'):signup(0);
